import sys
try:
    import markupsafe
except ImportError:
    sys.path.insert(0, 'src')
    import markupsafe
from markupsafe import Markup
class User:
    def __init__(self, id, name):
        self.id = id
        self.name = name
    def __html_format__(self, spec):
        if spec == 'link':
            return Markup('<a href="/user/{}">{}</a>').format(self.id, self.__html__())
        elif spec:
            raise ValueError('Invalid format spec')
        return self.__html__()
    def __html__(self):
        return Markup('<span class="user">{0}</span>').format(self.name)
u = User(3, 'Alice "The <b>Great</b>"')
out = Markup('{user:link}').format(user=u)
assert str(out) == '<a href="/user/3"><span class="user">Alice &#34;The &lt;b&gt;Great&lt;/b&gt;&#34;</span></a>', out

import sys
try:
    import markupsafe
except ImportError:
    sys.path.insert(0, 'src')
    import markupsafe
from markupsafe import Markup
c = Markup('&lt;script&gt;alert(document.cookie);&lt;/script&gt;')
assert str(Markup('{comment}').format(comment=c)) == '&lt;script&gt;alert(document.cookie);&lt;/script&gt;'
try:
    Markup('{comment:>40}').format(comment=c)
except ValueError as e:
    assert str(e) == 'Unsupported format specification for Markup.', e
else:
    raise AssertionError('expected ValueError')

