from markupsafe import Markup, escape
class User:
    def __init__(self, id, name):
        self.id = id
        self.name = name
    def __html_format__(self, spec):
        return Markup('<FORMAT>')
    def __html__(self):
        return Markup('<span class="user">{0}</span>').format(self.name)
r = escape(User(3, 'Alice "The <b>Great</b>"'))
assert type(r) is Markup
assert str(r) == '<span class="user">Alice &#34;The &lt;b&gt;Great&lt;/b&gt;&#34;</span>', r

import sys
try:
    import markupsafe
except ImportError:
    sys.path.insert(0, 'src')
    import markupsafe
from markupsafe import escape, Markup
class Proxy:
    def __init__(self, v):
        self._v = v
    @property
    def __class__(self):
        return self._v.__class__
    def __str__(self):
        return str(self._v)
p = Proxy('<x>')
assert isinstance(p, str) and type(p) is not str
assert str(escape(p)) == '&lt;x&gt;'
class Sub(str):
    def __str__(self):
        return self
assert str(escape(Sub('<x>'))) == '&lt;x&gt;'
assert str(escape(Markup('<x>'))) == '<x>'

import sys
try:
    import markupsafe
except ImportError:
    sys.path.insert(0, 'src')
    import markupsafe
from markupsafe import Markup
class OnlyHtml:
    def __html__(self):
        return Markup('<foo>')
class Both(OnlyHtml):
    def __html_format__(self, spec):
        return Markup('<FORMAT>')
assert str(Markup('{0}').format(OnlyHtml())) == '<foo>'
assert str(Markup('{0}').format(Both())) == '<FORMAT>'
assert str(Markup('{0}').format('<x>')) == '&lt;x&gt;'
try:
    Markup('{0:>10}').format(OnlyHtml())
except ValueError as e:
    assert 'does not define __html_format__' in str(e), e
else:
    raise AssertionError('expected ValueError')
